package com.sureshtrb.enKarma  import android.app.ProgressDialog import android.content.DialogInterface import android.os.Bundle import android.util.Log import androidx.appcompat.app.AlertDialog import androidx.appcompat.app.AppCompatActivity import com.google.firebase.auth.FirebaseAuth import com.sureshtrb.enKarma.databinding.ActivityForgotPasswordBinding  class ForgotPasswordActivity : AppCompatActivity() {      private lateinit var binding: ActivityForgotPasswordBinding     private var mProgress: ProgressDialog? = null      override fun onCreate(savedInstanceState: Bundle?) {         super.onCreate(savedInstanceState)         binding = ActivityForgotPasswordBinding.inflate(layoutInflater)         setContentView(binding.root)         mProgress = ProgressDialog(this)          supportActionBar?.setDisplayShowHomeEnabled(true)         supportActionBar?.setHomeAsUpIndicator(R.drawable.home)         supportActionBar?.setLogo(R.drawable.karma)         supportActionBar?.setDisplayUseLogoEnabled(true)         supportActionBar?.setTitle("சங்கேதமொழி சீர்செய்ய..")          binding.bForgotPassword.setOnClickListener { resetPassword() }     }      private fun alertDisplayer(title: String?, message: String?) {         AlertDialog.Builder(this@ForgotPasswordActivity)             .setTitle(title)             .setMessage(message)             .setPositiveButton("OK") { dialog: DialogInterface?, _: Int -> dialog?.cancel() }             .create()             .show()     }      private fun resetPassword() {
    binding.editEmail.text.toString().trim { it <= ' ' }         mProgress?.setMessage("Please wait...")         mProgress?.show()          FirebaseAuth.getInstance().sendPasswordResetEmail(email)             .addOnCompleteListener { task ->                 mProgress?.dismiss()                 if (task.isSuccessful) {                     Log.d("ForgotPassword", "Email sent.")                     val title = "Password Reset Email Sent!"                     "Check Your Email To Change Your Password"                     alertDisplayer(title, message)                 } else {                     Log.w("ForgotPassword", "Email not sent.", task.exception)                     val title = "Password Reset Failed"                     "Password cannot be changed"                     alertDisplayer(title, message + " :" + task.exception?.message)                 }             }
} }